style.css:
@-moz-document domain("youtube.com") {
/* Fondo general tipo escritorio XP */
  body, #content {
    background: linear-gradient(180deg, #3a6ea5 0%, #2b579a 100%) !important;
    color: #fff !important;
    font-family: "Tahoma", "Verdana", sans-serif !important;
  }

  /* Cabecera superior (barra de tareas estilo XP) */
  #masthead-container {
    background: linear-gradient(180deg, #245edc 0%, #1c4abf 100%) !important;
    border-bottom: 3px solid #0b2e8a !important;
    box-shadow: inset 0 1px 0 #69a1f4, 0 2px 4px rgba(0,0,0,0.4) !important;
  }

  /* Botones estilo XP */
  ytd-topbar-menu-button-renderer button,
  #buttons ytd-button-renderer,
  tp-yt-paper-button {
    background: linear-gradient(180deg, #e4ecf7 0%, #c9d7f2 100%) !important;
    border: 2px solid #4a77d4 !important;
    border-radius: 4px !important;
    color: #003366 !important;
    font-weight: bold !important;
    box-shadow: 1px 1px 2px #1c3b7b inset !important;
  }

  ytd-topbar-menu-button-renderer button:hover,
  tp-yt-paper-button:hover {
    background: linear-gradient(180deg, #fff 0%, #dfeaff 100%) !important;
  }

  /* Barra de búsqueda */
  #search-input #search {
    background: #f4f8fc !important;
    border: 2px solid #5a7ee6 !important;
    border-radius: 4px !important;
    color: #000 !important;
  }

  /* Botón buscar */
  #search-icon-legacy {
    background: linear-gradient(180deg, #d7e3f4 0%, #b3c7f0 100%) !important;
    border: 2px solid #3c6edc !important;
  }

  /* Videos y miniaturas */
  ytd-rich-item-renderer {
    background: #e7eefc !important;
    border: 2px solid #6c8edc !important;
    border-radius: 6px !important;
    margin: 8px !important;
    box-shadow: 2px 2px 4px rgba(0,0,0,0.3) !important;
  }

  ytd-rich-item-renderer:hover {
    background: #f8fbff !important;
    border-color: #4c78e0 !important;
  }

  /* Títulos de videos */
  #video-title {
    color: #002c77 !important;
    font-weight: bold !important;
  }

  /* Panel lateral */
  #guide-content {
    background: #d9e5f9 !important;
    border-right: 3px solid #4f74ce !important;
  }

  /* Botones de guía */
  ytd-guide-entry-renderer:hover {
    background: #c7dbfa !important;
  }

  /* Reproductor */
  .html5-video-player {
    border: 3px solid #0044cc !important;
    border-radius: 8px !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.5) !important;
  }

  /* Comentarios */
  ytd-comment-renderer {
    background: #f0f6ff !important;
    border: 1px solid #a3c0ff !important;
    border-radius: 6px !important;
    padding: 8px !important;
  }

  /* Scroll retro */
  ::-webkit-scrollbar {
    width: 12px;
    background: #d8e4f8;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #5b82e6, #3565cc);
    border: 2px solid #d8e4f8;
    border-radius: 6px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #6b92f6, #3f74e6);
  }
}
